/**
 * build-workbook-bundle.mjs
 *
 * Reads all 10 Brunson strategy workbooks from ../../strategy/workbooks/
 * and writes a single TypeScript module at src/lib/workbooks-bundle.ts.
 *
 * Run:  node scripts/build-workbook-bundle.mjs
 * Auto: wired as "prebuild" in package.json so Vercel runs it before next build.
 *
 * The output file is committed so local dev works without running the script,
 * but Vercel always regenerates from source on deploy.
 */

import { readFileSync, writeFileSync, readdirSync } from 'fs'
import { join, resolve, dirname } from 'path'
import { fileURLToPath } from 'url'

const __dirname = dirname(fileURLToPath(import.meta.url))

// ../../strategy/workbooks relative to app/scripts/
const WORKBOOKS_DIR = resolve(__dirname, '../../strategy/workbooks')
const OUTPUT_PATH   = resolve(__dirname, '../src/lib/workbooks-bundle.ts')

const WORKBOOK_META = [
  { slug: '01-sales-funnel-secrets',  title: 'The Secret Formula',         number: 1  },
  { slug: '02-funnels-value-ladder',  title: 'Value Ladder',               number: 2  },
  { slug: '03-funnel-scripts',        title: 'Funnel Scripts',             number: 3  },
  { slug: '04-building-your-funnels', title: 'Building Your Funnels',      number: 4  },
  { slug: '05-creating-your-movement',title: 'Creating Your Movement',     number: 5  },
  { slug: '06-creating-belief',       title: 'Creating Belief',            number: 6  },
  { slug: '07-10x-secrets-one-to-many','title': '10x Secrets',             number: 7  },
  { slug: '08-your-dream-customer',   title: 'Your Dream Customer',        number: 8  },
  { slug: '09-fill-your-funnel',      title: 'Fill Your Funnel',           number: 9  },
  { slug: '10-growth-hacking',        title: 'Growth Hacking',             number: 10 },
]

function escapeBacktick(s) {
  return s.replace(/\\/g, '\\\\').replace(/`/g, '\\`').replace(/\$\{/g, '\\${')
}

const workbooks = WORKBOOK_META.map(({ slug, title, number }) => {
  const filePath = join(WORKBOOKS_DIR, `${slug}.md`)
  const content  = readFileSync(filePath, 'utf-8')
  return { slug, title, number, content }
})

// Build the concatenated system-prompt context block
const systemContext = workbooks.map(({ slug, title, number, content }) =>
  `=== WORKBOOK ${String(number).padStart(2, '0')}: ${title.toUpperCase()} ===\n` +
  `Citation path: /playbook/workbook/${slug}\n\n` +
  content
).join('\n\n' + '─'.repeat(60) + '\n\n')

const out = `/**
 * AUTO-GENERATED by scripts/build-workbook-bundle.mjs
 * DO NOT EDIT MANUALLY — run \`node scripts/build-workbook-bundle.mjs\` to refresh.
 * Source: strategy/workbooks/*.md (${workbooks.length} workbooks, ${systemContext.length.toLocaleString()} chars)
 */

export type Workbook = {
  slug: string
  title: string
  number: number
  content: string
}

export const WORKBOOKS: Workbook[] = [
${workbooks.map(({ slug, title, number, content }) =>
  `  {\n    slug: '${slug}',\n    title: ${JSON.stringify(title)},\n    number: ${number},\n    content: \`${escapeBacktick(content)}\`,\n  },`
).join('\n')}
]

/**
 * Full concatenated context for the AI system prompt.
 * Includes headers + citation paths so the model knows how to cite each workbook.
 */
export const WORKBOOKS_SYSTEM_CONTEXT: string = \`${escapeBacktick(systemContext)}\`
`

writeFileSync(OUTPUT_PATH, out, 'utf-8')
console.log(`[workbook-bundle] Wrote ${workbooks.length} workbooks → src/lib/workbooks-bundle.ts (${out.length.toLocaleString()} bytes)`)
